var BookmarkImportModal = class extends Modal {
  constructor(plugin, pageId) {
    super(plugin.app);
    this.plugin = plugin;
    this.pageId = pageId;
    this.modalEl.addClass("qh-ui");
  }
  plugin;
  pageId;
  onOpen() {
    this.setTitle(L("\u5BFC\u5165\u6D4F\u89C8\u5668\u4E66\u7B7E", "Import browser bookmarks"));
    this.contentEl.createEl("p", { text: L("\u9009\u62E9\u6D4F\u89C8\u5668\u5BFC\u51FA\u7684 HTML \u6587\u4EF6\uFF0C\u9884\u89C8\u540E\u5BFC\u5165\u4E3A\u4E00\u4E2A\u5FEB\u6377\u65B9\u5F0F\u7EC4\u3002\u6700\u591A\u5BFC\u5165\u524D 50 \u4E2A\u4E0D\u540C\u7684\u7F51\u5740\u3002", "Choose an exported HTML bookmark file. Preview and import up to 50 unique websites as a shortcut group.") });
    let bookmarks = [];
    const input = this.contentEl.createEl("input", { type: "file", attr: { accept: ".html,.htm,text/html" } });
    input.id = `qh-bookmarks-${crypto.randomUUID()}`;
    this.contentEl.createEl("label", { cls: "qh-sr-only", text: L("\u4E66\u7B7E HTML \u6587\u4EF6", "Bookmark HTML file"), attr: { for: input.id } });
    const preview = this.contentEl.createDiv({ cls: "qh-bookmark-preview" });
    const footer = new Setting(this.contentEl);
    footer.addButton((button) => {
      button.setButtonText(L("\u5BFC\u5165", "Import")).setDisabled(true).setCta();
      input.addEventListener("change", () => {
        bookmarks = [];
        button.setDisabled(true);
        preview.empty();
        const file = input.files?.[0];
        if (!file) return;
        if (file.size > 2e6) {
          preview.setText(L("\u6587\u4EF6\u9700\u5C0F\u4E8E 2 MB", "File must be smaller than 2 MB"));
          return;
        }
        void file.text().then((text3) => {
          if (!this.contentEl.isConnected || input.files?.[0] !== file) return;
          bookmarks = parseBookmarks(text3, decodeBookmarkText);
          preview.createEl("p", { text: L("\u5C06\u5BFC\u5165 {length} \u4E2A\u7F51\u5740", "{length} websites to import", { length: bookmarks.length }) });
          for (const item of bookmarks.slice(0, 8)) preview.createDiv({ text: `${item.name} \xB7 ${new URL(item.url).hostname}` });
          button.setDisabled(!bookmarks.length);
        }).catch((error) => preview.setText(error instanceof Error ? error.message : L("\u8BFB\u53D6\u5931\u8D25", "Could not read bookmarks")));
      });
      button.onClick(async () => {
        const page = this.plugin.settings.pages.find((page2) => page2.id === this.pageId);
        if (!page || !bookmarks.length) return;
        const group = { id: crypto.randomUUID(), name: L("\u5BFC\u5165\u7684\u4E66\u7B7E", "Imported bookmarks"), items: bookmarks.map((item) => ({ id: crypto.randomUUID(), kind: "url", target: item.url, name: item.name, icon: "globe" })) };
        const key = shortcutModuleId(group.id);
        page.shortcutGroups.push(group);
        page.moduleOptions[key] = { visible: true, limit: 3 };
        page.moduleOrder.push(key);
        button.setDisabled(true);
        try {
          await this.plugin.saveSettings();
          this.close();
        } catch {
          page.shortcutGroups = page.shortcutGroups.filter((item) => item !== group);
          page.moduleOrder = page.moduleOrder.filter((id) => id !== key);
          delete page.moduleOptions[key];
          button.setDisabled(false);
          new Notice(t("layout.saveFailed"));
        }
      });
    });
  }
  onClose() {
    this.contentEl.empty();
  }
};

